// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 g) public {
        vm.assume(actor != address(0));
        vm.deal(actor, 2 ether);

        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(g);

        // Reference records target = block.number + 1, so settling at
        // block.number + 2 satisfies `block.number > guesses[actor].block`.
        // The mutant records block.number + 2, so settle reverts here.
        vm.roll(block.number + 2);

        vm.prank(actor);
        try c.settle() {
            assertTrue(true);
        } catch {
            assertTrue(false, "settle at target+1 blocks must succeed");
        }
    }
}
